function toast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>e.classList.remove('show'),3600);}
function persist(){try{localStorage.setItem('isla-trip-v1',JSON.stringify(state));}catch{toast(t('persistError'));}}
function snapshot(){ui.undo=structuredClone(state);}
function mutate(fn,msg){snapshot();fn();persist();render();if(msg)toast(msg);}
function formatDate(date,opts={month:'short',day:'numeric'}){return new Date(date+'T12:00:00Z').toLocaleDateString(state.lang==='zh'?'zh-TW':'en-US',{...opts,timeZone:'UTC'});}
function badge(p){return '<span class="badge '+esc(p.region)+'">'+esc(t(p.region))+'</span>';}
function image(p,cls=''){return '<img class="'+cls+'" src="'+esc(images[p.image]||images.beach)+'" alt="" loading="lazy" referrerpolicy="no-referrer">';}
function recCard(p){const saved=(state.bookmarks||[]).includes(p.id);return '<article class="rec-card"><div class="rec-image">'+image(p)+'<button class="bookmark '+(saved?'saved':'')+'" data-action="bookmark" data-id="'+esc(p.id)+'" aria-pressed="'+saved+'" aria-label="'+esc(t(saved?'unbookmarked':'bookmarked')+' '+name(p))+'">'+icon('heart')+'</button></div><div class="rec-content">'+badge(p)+' <span class="muted small">· '+esc(t(p.type))+'</span><h3>'+esc(name(p))+'</h3><p>'+esc(desc(p))+'</p><div class="rec-bottom"><a href="'+esc(safeUrl(p.source))+'" target="_blank" rel="noopener noreferrer">'+esc(t('source'))+' ↗</a>'+btn(t('add'),'add','plus','','data-id="'+esc(p.id)+'"')+'</div></div></article>';}
function itemCard(item,index,items){const p=place(item.placeId);if(!p)return '';return '<article class="itinerary-card" data-stop="'+esc(item.id)+'">'+image(p,'thumb')+'<div class="card-info">'+badge(p)+'<h3>'+esc(name(p))+'</h3><div class="card-meta"><span>'+esc(t(p.type))+'</span><span>· '+p.duration+' '+esc(t('duration'))+'</span><button data-action="locate" data-id="'+esc(p.id)+'" class="small" aria-label="'+esc(t('map')+' '+name(p))+'">'+icon('pin')+'</button></div><p class="card-note">'+esc(item.note||desc(p))+'</p></div><div class="card-actions"><button data-action="edit-item" data-id="'+esc(item.id)+'" aria-label="'+esc(t('edit')+' '+name(p))+'">'+icon('edit')+'</button><button data-action="move-up" data-id="'+esc(item.id)+'" aria-label="'+esc(t('moveUp')+' '+name(p))+'" '+(index===0?'disabled':'')+'>'+icon('up')+'</button><button data-action="move-down" data-id="'+esc(item.id)+'" aria-label="'+esc(t('moveDown')+' '+name(p))+'" '+(index===items.length-1?'disabled':'')+'>'+icon('down')+'</button><button data-action="remove" data-id="'+esc(item.id)+'" aria-label="'+esc(t('remove')+' '+name(p))+'">'+icon('trash')+'</button></div></article>';}
function warnings(items,date){return warningsFor(items,state.places,date).map(w=>'<div class="warning">'+icon(w==='moon'?'moon':'info')+'<div>'+esc(t(({ferry:'ferryWarning',moon:'moonWarning'})[w]||w))+(w==='moon'?' <a href="https://www.timeanddate.com/moon/puerto-rico/san-juan?month=12&year=2026" target="_blank" rel="noopener noreferrer">↗</a>':'')+(w==='ferry'?' <a href="https://www.puertoricoferry.com/en/buy-tickets/" target="_blank" rel="noopener noreferrer">'+esc(t('source'))+' ↗</a>':'')+'</div></div>').join('');}
function dayView(){const dates=datesBetween(state.trip.start,state.trip.end);const items=state.items.filter(i=>i.date===ui.date);let out='<div class="date-strip">'+dates.map((date,i)=>'<button data-action="date" data-date="'+date+'" class="day '+(date===ui.date?'active':'')+'" aria-pressed="'+(date===ui.date)+'"><span class="small">'+esc(t('day'))+' '+(i+1)+'</span><strong>'+esc(formatDate(date))+'</strong><span class="dots">'+(state.items.filter(x=>x.date===date).length?'● '.repeat(Math.min(5,state.items.filter(x=>x.date===date).length)):'○')+'</span></button>').join('')+'</div><div class="day-tools"><div class="day-title"><h3>'+esc(formatDate(ui.date,{weekday:'long',month:'long',day:'numeric'}))+'</h3><p>'+items.length+' '+esc(t('stops'))+' · '+items.reduce((s,i)=>s+(place(i.placeId)?.duration||0),0)+' '+esc(t('duration'))+'</p></div><div class="toolbar">'+btn(t('undo'),'undo','undo','','aria-label="'+esc(t('undo'))+'" '+(!ui.undo?'disabled':''))+btn(t('optimize'),'optimize','sparkles')+'</div></div>'+warnings(items,ui.date);for(const slot of ['morning','afternoon','evening']){const slotItems=items.filter(i=>i.slot===slot);out+='<section class="period"><div class="period-icon">'+icon(slot==='morning'?'sun':slot==='afternoon'?'afternoon':'moon')+'</div><div><div class="period-heading"><div>'+esc(t(slot))+'<span>'+esc(t(slot+'Time'))+'</span></div><button data-action="add" data-slot="'+slot+'" aria-label="'+esc(t('addStop')+' · '+t(slot))+'">'+icon('plus')+'</button></div><div class="period-content">'+(slotItems.length?slotItems.map((item,index)=>{const prev=index?place(slotItems[index-1].placeId):null;const current=place(item.placeId);return (prev&&current?'<div class="stop-gap">'+km(prev,current).toFixed(1)+' '+esc(t('distance'))+'</div>':'')+itemCard(item,index,slotItems);}).join(''):'<button class="empty-slot" data-action="add" data-slot="'+slot+'">+ '+esc(t('emptySlot'))+'</button>')+'</div></div></section>';}
const outside=state.items.filter(x=>!dates.includes(x.date));if(outside.length)out+='<section><h3>'+esc(t('unassigned'))+' ('+outside.length+')</h3><p class="small muted">'+esc(t('unassignedHint'))+'</p>'+outside.map(i=>'<div class="settings-box">'+esc(i.date+' · '+name(place(i.placeId)))+' '+btn(t('edit'),'edit-item','edit','','data-id="'+esc(i.id)+'"')+'</div>').join('')+'</section>';out+='<section class="suggestion-section"><div class="section-heading"><h3>'+esc(t('picked'))+'</h3><button data-action="view" data-view="discover">'+esc(t('pickedSub'))+' ↗</button></div><div class="recommend-grid">'+['flamenco','tamarindo'].map(id=>place(id)).filter(Boolean).map(recCard).join('')+'</div></section>';if(state.trip.comparisonPlan&&ui.date>=context.start&&ui.date<context.end){const area=state.trip.comparisonStay==='split'&&ui.date>='2026-12-22'?'Luquillo / Fajardo':state.lang==='zh'?'San Juan 都會區':'Metro San Juan';out='<div class="comparison-arrival"><strong>'+esc(state.lang==='zh'?'今晚住宿規劃區域 · '+area:'Tonight’s planned base · '+area)+'</strong><br>'+esc(state.lang==='zh'?'私人房間，可共用衛浴；五晚含費總額上限 US$450。房源及預訂待確認。':'Private room, shared bathroom OK; US$450 all-in cap for five nights. Property and reservation to be confirmed.')+'</div>'+out;}if(state.trip.comparisonPlan&&[context.start,context.end].includes(ui.date))out='<div class="comparison-arrival">'+esc(comparisonCopy[state.lang][ui.date===context.start?'arrival':'departure'])+'</div>'+out;return out;}
function discovery(){let p=searchPlaces(state.places,ui.query,ui.filter,ui.region);if(ui.view==='saved')p=p.filter(p=>(state.bookmarks||[]).includes(p.id));return '<form id="search-form" class="search-bar"><label class="sr-only" for="place-search">'+esc(t('search'))+'</label><input id="place-search" name="query" value="'+esc(ui.query)+'" placeholder="'+esc(t('searchPlaceholder'))+'">'+btn(t('search'),'search','search','primary','type="submit"')+'</form><div class="filters">'+['all','sight','beach','nature','food','hotel','bio'].map(type=>'<button data-action="filter" data-filter="'+type+'" class="'+(ui.filter===type?'active':'')+'" aria-pressed="'+(ui.filter===type)+'">'+esc(t(type))+'</button>').join('')+'</div><div class="filter-row"><span class="muted small">'+p.length+' '+esc(t('stops'))+'</span><select id="region-filter" aria-label="'+esc(t('map'))+'">'+['all','main','c','v','other'].map(r=>'<option value="'+r+'" '+(ui.region===r?'selected':'')+'>'+esc(t(r))+'</option>').join('')+'</select></div>'+(p.length?'<div class="recommend-grid">'+p.map(recCard).join('')+'</div>':'<div class="empty">'+icon(ui.view==='saved'?'heart':'search')+'<h3>'+esc(t(ui.view==='saved'?'noSaved':'noResults'))+'</h3><p>'+esc(t(ui.view==='saved'?'savedHint':'noResultHint'))+'</p>'+btn(t('globalSearch'),'global','search','primary')+'</div>')+'<div class="bottom-note">'+icon('info')+esc(t('defaultOnly'))+'</div><div class="toolbar" style="margin-top:12px;flex-wrap:wrap">'+btn(t('globalSearch'),'global','search')+btn(t('newPlace'),'custom','plus')+'</div>';}
function mapSvg(){let ps=ui.view==='stays'&&ui.stayResults.length?ui.stayResults:ui.mapScope==='day'?state.items.filter(i=>i.date===ui.date).map(i=>place(i.placeId)).filter(Boolean):state.places;ps=[...new Map(ps.map(p=>[p.id,p])).values()];if(!ps.length)ps=seed;const selected=place(ui.selected)||ps[0];const pr=ps.every(p=>p.lat>17.8&&p.lat<18.7&&p.lon>-67.5&&p.lon<-65);const W=580,H=340;let minLon,maxLon,minLat,maxLat;if(pr){minLon=-66.68;maxLon=-65.14;minLat=17.95;maxLat=18.61;}else{minLon=Math.min(...ps.map(p=>p.lon))-.12;maxLon=Math.max(...ps.map(p=>p.lon))+.12;minLat=Math.min(...ps.map(p=>p.lat))-.10;maxLat=Math.max(...ps.map(p=>p.lat))+.10;}const cx=ui.zoom>1?selected.lon:(minLon+maxLon)/2;const cy=ui.zoom>1?selected.lat:(minLat+maxLat)/2;const spanX=(maxLon-minLon)/ui.zoom,spanY=(maxLat-minLat)/ui.zoom;minLon=cx-spanX/2;maxLon=cx+spanX/2;minLat=cy-spanY/2;maxLat=cy+spanY/2;const proj=(lon,lat)=>[(lon-minLon)/(maxLon-minLon)*W,H-(lat-minLat)/(maxLat-minLat)*H];const poly=coords=>coords.map(([lon,lat])=>proj(lon,lat).join(',')).join(' ');let content='<defs><pattern id="grid" width="29" height="29" patternUnits="userSpaceOnUse"><path d="M29 0H0V29" fill="none" stroke="#d8e4dc" stroke-width=".5"/></pattern><clipPath id="clip"><rect width="580" height="340"/></clipPath></defs><rect width="580" height="340" fill="#e8f0ec"/><rect width="580" height="340" fill="url(#grid)"/><g clip-path="url(#clip)">';if(pr){const mainland=[[-67.25,18.37],[-67.13,18.49],[-66.8,18.49],[-66.5,18.49],[-66.25,18.47],[-66.13,18.47],[-66.05,18.43],[-65.87,18.45],[-65.73,18.39],[-65.64,18.39],[-65.59,18.35],[-65.63,18.28],[-65.6,18.23],[-65.65,18.18],[-65.74,18.14],[-65.79,18.06],[-65.88,17.98],[-66.1,17.98],[-66.37,17.94],[-66.6,17.99],[-66.92,17.97],[-67.2,17.97],[-67.17,18.15]];const culebra=[[-65.34,18.34],[-65.31,18.34],[-65.29,18.31],[-65.25,18.32],[-65.24,18.29],[-65.29,18.28],[-65.31,18.29],[-65.34,18.31]];const vieques=[[-65.58,18.13],[-65.49,18.15],[-65.39,18.14],[-65.28,18.11],[-65.3,18.09],[-65.45,18.08],[-65.56,18.1]];for(const shape of [mainland,culebra,vieques])content+='<polygon points="'+poly(shape)+'" fill="#d9e4cf" stroke="#b7c9ae" stroke-width="1.1"/>';for(const row of [[-66.27,18.22,'PUERTO RICO'],[-65.29,18.38,'CULEBRA'],[-65.40,18.045,'VIEQUES']]){const [x,y]=proj(row[0],row[1]);content+='<text x="'+x+'" y="'+y+'" text-anchor="middle" font-size="12" fill="#7c9675" font-family="sans-serif" letter-spacing="2">'+row[2]+'</text>';}}else{content+='<path d="M-20 70Q130 140 220 65T620 95M-20 260Q180 185 330 270T620 210" stroke="#d4dfc8" stroke-width="55" fill="none"/>';}
const dayItems=state.items.filter(i=>i.date===ui.date).map(i=>place(i.placeId)).filter(Boolean);if(dayItems.length>1&&ui.view!=='stays')content+='<polyline points="'+poly(dayItems.map(p=>[p.lon,p.lat]))+'" stroke="#6d9465" stroke-width="2" stroke-dasharray="5 5" fill="none" opacity=".65"/>';const occupied=[];ps.forEach((p,i)=>{const [anchorX,anchorY]=proj(p.lon,p.lat);let x=anchorX,y=anchorY;for(let attempt=0;attempt<70;attempt++){if(!occupied.some(q=>Math.hypot(q[0]-x,q[1]-y)<30))break;const angle=attempt*2.399963;const radius=22+5*Math.sqrt(attempt);x=anchorX+Math.cos(angle)*radius;y=anchorY+Math.sin(angle)*radius;}occupied.push([x,y]);const picked=p.id===ui.selected;const color=({c:'#548f91',v:'#9581a8'})[p.region]||'#4d7658';if(Math.hypot(x-anchorX,y-anchorY)>1)content+='<line x1="'+anchorX+'" y1="'+anchorY+'" x2="'+x+'" y2="'+y+'" stroke="#9bad94" stroke-width=".8"/>';content+='<g class="map-pin" tabindex="0" role="button" aria-label="'+esc(name(p))+'" data-action="locate" data-id="'+esc(p.id)+'" transform="translate('+x+','+y+')"><title>'+esc(name(p))+'</title>'+(picked?'<circle r="19" fill="'+color+'" opacity=".13"/>':'')+'<circle r="'+(picked?12:9)+'" fill="'+color+'" stroke="white" stroke-width="2"/><text text-anchor="middle" dy="3.3" font-size="9" font-family="sans-serif" fill="white">'+(i+1)+'</text></g>';});return '<svg viewBox="0 0 580 340" role="group" aria-label="'+esc(t('mapTitle'))+'">'+content+'</g></svg>';}
function mapPanel(){const selected=place(ui.selected)||state.places[0];const today=ui.view==='stays'&&ui.stayResults.length?ui.stayResults:state.items.filter(i=>i.date===ui.date).map(i=>place(i.placeId)).filter(Boolean);const distance=ui.view==='stays'&&stayAnchor()&&selected?km(stayAnchor(),selected):today.reduce((s,p,i)=>s+(i?km(today[i-1],p):0),0);const regions=new Set(ui.view==='stays'?today.map(p=>p.region):state.items.map(i=>place(i.placeId)?.region).filter(Boolean));const src=selected?'https://www.openstreetmap.org/export/embed.html?bbox='+[selected.lon-.06,selected.lat-.04,selected.lon+.06,selected.lat+.04].join('%2C')+'&layer=mapnik&marker='+selected.lat+'%2C'+selected.lon:'';return '<section class="panel '+(ui.view==='map'?'view-map':'')+'" id="map-panel"><div class="panel-header"><h3>'+icon('map')+esc(t('mapTitle'))+'</h3><div class="map-tabs">'+['overview','street'].map(mode=>'<button data-action="map-mode" data-mode="'+mode+'" class="'+(ui.mapMode===mode?'active':'')+'">'+esc(t(mode))+'</button>').join('')+'</div></div><div class="map-wrap">'+(ui.mapMode==='street'?'<iframe src="'+esc(src)+'" title="OpenStreetMap" loading="lazy" referrerpolicy="no-referrer"></iframe>':mapSvg()+'<div class="map-controls"><button data-action="zoom-in" aria-label="Zoom in">'+icon('plus')+'</button><button data-action="zoom-out" aria-label="Zoom out">'+icon('minus')+'</button><button data-action="zoom-reset" aria-label="'+esc(t('overview'))+'">'+icon('refresh')+'</button></div><span class="map-credit">'+esc(t('mapCredit'))+'</span>')+'</div><div class="map-legend"><span><i class="legend-dot"></i>'+esc(t('main'))+'</span><span><i class="legend-dot c"></i>Culebra</span><span><i class="legend-dot v"></i>Vieques</span><button data-action="map-scope" style="margin-left:auto;font-size:9px">'+esc(t(ui.mapScope==='all'?'todayOnly':'allPlaces'))+'</button></div>'+(selected?'<div class="map-selection"><strong>'+esc(name(selected))+'</strong><p>'+esc(t(selected.region))+' · '+esc(t(selected.type))+'</p><div class="toolbar">'+btn(t('add'),'add','plus','','data-id="'+esc(selected.id)+'"')+link(t('navigate'),'https://www.google.com/maps/dir/?api=1&destination='+selected.lat+','+selected.lon,'external')+'</div></div>':'')+'<div class="stats"><div><strong>'+today.length+'</strong><span>'+esc(t(ui.view==='stays'?'stayResults':'stops'))+'</span></div><div><strong>'+distance.toFixed(1)+'</strong><span>'+esc(t('distance'))+'</span></div><div><strong>'+regions.size+'</strong><span>'+esc(t('islands'))+'</span></div></div><div class="offline-label">'+esc(t('mapTip'))+'</div></section>';}
function assistant(){return '<section class="assistant" id="assistant-panel"><div class="assistant-top"><h3>'+icon('sparkles')+esc(t('aiTitle'))+'</h3><span class="mode">'+esc(t(ui.aiLive?'live':'demo'))+'</span></div><p>'+esc(t('aiIntro'))+'</p><div class="prompt-chips">'+['chipFood','chipStay','chipIsland','chipOptimize'].map(k=>'<button data-action="prompt" data-prompt="'+k+'">'+esc(t(k))+'</button>').join('')+'</div><form id="ask-form" class="ask-box"><label class="sr-only" for="ai-prompt">'+esc(t('aiTitle'))+'</label><textarea id="ai-prompt" name="prompt" placeholder="'+esc(t('askPlaceholder'))+'" maxlength="1500" '+(ui.busy?'disabled':'')+'>'+esc(ui.prompt)+'</textarea><button type="submit" aria-label="'+esc(t('send'))+'" '+(ui.busy?'disabled':'')+'>'+icon('send')+'</button></form><div class="assistant-foot">'+icon('info')+esc(t(ui.aiLive?'liveNote':'demoNote'))+'</div>'+(ui.busy?'<div class="chat-response" role="status">'+esc(t('working'))+'</div>':ui.chat?'<div class="chat-response" aria-live="polite">'+esc(ui.chat)+ui.chatIds.map(place).filter(Boolean).map(p=>'<div class="ai-result"><span>'+esc(name(p))+'<br><span style="opacity:.65">'+esc(t(p.region))+'</span></span><button data-action="add" data-id="'+esc(p.id)+'">+ '+esc(t('add'))+'</button></div>').join('')+(ui.chatSort?'<div style="margin-top:10px">'+btn(t('applySort'),'optimize','route','light')+'</div>':'')+'</div>':'')+'</section>';}

function stayAnchor(){return state.items.filter(i=>i.date===ui.date).map(i=>place(i.placeId)).find(p=>p&&p.type!=='hotel');}
function lodgingCard(p){const saved=(state.bookmarks||[]).includes(p.id),anchor=stayAnchor(),search=ui.stayApplied||ui.staySearch;const booking=bookingSearch({...search,name:name(p),lang:state.lang});return '<article class="lodging-card" data-hotel="'+esc(p.id)+'"><div class="lodging-heading"><div class="lodging-icon">'+icon('bed')+'</div><div>'+badge(p)+'<h3>'+esc(name(p))+'</h3></div><button class="icon-btn bookmark '+(saved?'saved':'')+'" data-action="bookmark" data-id="'+esc(p.id)+'" aria-label="'+esc(t(saved?'unbookmarked':'bookmarked')+' '+name(p))+'" aria-pressed="'+saved+'">'+icon('heart')+'</button></div><p class="stay-address">'+icon('pin')+esc(p.address||t('stayDetailsMissing'))+'</p>'+(p.phone?'<p class="small muted">'+esc(t('stayPhone')+': '+p.phone)+'</p>':'')+(anchor?'<p class="stay-distance">'+icon('route')+km(anchor,p).toFixed(1)+' '+esc(t('stayDistanceLabel'))+'</p>':'')+'<div class="stay-links">'+link(t('stayRates'),booking,'external')+(p.website&&safeUrl(p.website)!=='#'?link(t('stayWebsite'),p.website):'')+'<a href="'+esc(safeUrl(p.source))+'" target="_blank" rel="noopener noreferrer">OpenStreetMap ↗</a></div><div class="stay-card-actions">'+btn(t('stayMap'),'locate','map','','data-id="'+esc(p.id)+'"')+btn(t('stayAdd'),'stay-add','plus','primary','data-id="'+esc(p.id)+'"')+'</div></article>';}
function staysView(){const search=ui.staySearch,applied=ui.stayApplied;let booking='#';try{booking=bookingSearch({...search,lang:state.lang});}catch{}let results=[...ui.stayResults];const anchor=stayAnchor();results.sort((a,b)=>ui.staySort==='distance'&&anchor?km(anchor,a)-km(anchor,b):name(a).localeCompare(name(b)));return stayComparisonBanner(state.lang)+'<section class="stays-intro"><h2>'+esc(t('stayTitle'))+'</h2><p>'+esc(t('stayIntro'))+'</p></section><form id="stay-form" class="stay-form"><label class="form-field">'+esc(t('stayCity'))+'<input name="city" required maxlength="120" value="'+esc(search.city)+'" placeholder="'+esc(t('stayPlaceholder'))+'"></label><div class="stay-date-grid"><label class="form-field">'+esc(t('checkin'))+'<input type="date" name="checkin" value="'+esc(search.checkin)+'" required></label><label class="form-field">'+esc(t('checkout'))+'<input type="date" name="checkout" value="'+esc(search.checkout)+'" required></label><label class="form-field">'+esc(t('guests'))+'<input type="number" name="guests" value="'+esc(search.guests)+'" min="1" max="20" required></label></div><div class="stay-form-bottom"><span class="small muted">'+esc(t('stayHint'))+'</span><button class="btn primary" type="submit" '+(ui.stayStatus==='loading'?'disabled':'')+'>'+icon('search')+esc(t(ui.stayStatus==='loading'?'stayLoading':'staySearch'))+'</button></div>'+(ui.stayError?'<p class="form-error" role="alert">'+esc(ui.stayError)+'</p>':'')+'</form><div class="warning">'+icon('info')+'<div>'+esc(t('stayPriceNote'))+'</div></div>'+(ui.stayStatus==='loading'?'<div class="empty" role="status">'+icon('bed')+'<p>'+esc(t('stayLoading'))+'</p></div>':results.length?'<div class="stay-result-summary"><strong>'+results.length+' '+esc(t('stayResults'))+'</strong><span>'+esc(t('stayDateNote'))+': '+esc(applied.checkin+' → '+applied.checkout)+' · '+stayNights(applied.checkin,applied.checkout)+' '+esc(t('nights'))+' · '+applied.guests+' '+esc(t('guestUnit'))+'</span></div><div class="stay-controls"><label>'+esc(t('stayCompareDay'))+'<select id="stay-compare">'+datesBetween(state.trip.start,state.trip.end).map(d=>'<option value="'+d+'" '+(ui.date===d?'selected':'')+'>'+esc(formatDate(d))+'</option>').join('')+'</select></label><label>'+esc(t('staySort'))+'<select id="stay-sort"><option value="distance" '+(ui.staySort==='distance'?'selected':'')+'>'+esc(t('stayDistance'))+'</option><option value="name" '+(ui.staySort==='name'?'selected':'')+'>'+esc(t('stayName'))+'</option></select></label></div>'+(anchor?'':'<p class="small muted">'+esc(t('stayNoAnchor'))+'</p>')+'<div class="lodging-grid">'+results.map(lodgingCard).join('')+'</div>':'<div class="empty">'+icon('bed')+'<h3>'+esc(t(ui.stayStatus==='error'?'stayUnavailable':ui.stayStatus==='empty'?'stayNone':'stayEmpty'))+'</h3><p>'+esc(t('stayEmptyHint'))+'</p>'+(booking!=='#'?link(t('stayRates'),booking,'external'):'')+'</div>');}

function render(){const params=new URLSearchParams(location.search);params.set('lang',state.lang);params.set('option',ui.comparePlan);params.set('stay',ui.compareStay);history.replaceState(null,'',location.pathname+'?'+params.toString()+(ui.view==='stays'?'#stays':ui.view==='compare'?'#compare':''));const days=datesBetween(state.trip.start,state.trip.end);if(!days.includes(ui.date))ui.date=days[0];document.documentElement.lang=state.lang==='zh'?'zh-Hant':'en';document.title='Isla · '+state.trip.destination;document.querySelector('#app').innerHTML='<aside class="rail"><div class="brand-mark">'+icon('compass')+'</div>'+['plan','compare','discover','stays','saved','map'].map(v=>'<button data-action="view" data-view="'+v+'" class="'+(ui.view===v?'active':'')+'" aria-label="'+esc(t(v))+'">'+icon(v==='discover'?'search':v==='saved'?'heart':v==='stays'?'bed':v==='compare'?'route':v)+'<span>'+esc(t(v))+'</span></button>').join('')+'<div class="rail-spacer"></div><button class="settings-rail" data-action="settings" aria-label="'+esc(t('settings'))+'">'+icon('settings')+'<span>'+esc(t('settings'))+'</span></button><button class="avatar" data-action="edit-trip" aria-label="'+esc(t('editTrip'))+'">J</button></aside><div class="shell"><header class="topbar"><div class="wordmark">isla<span>'+esc(t('tagline'))+'</span></div><div class="top-actions"><div class="language" aria-label="Language"><button data-action="lang" data-lang="zh" class="'+(state.lang==='zh'?'active':'')+'" aria-pressed="'+(state.lang==='zh')+'">繁中</button><button data-action="lang" data-lang="en" class="'+(state.lang==='en'?'active':'')+'" aria-pressed="'+(state.lang==='en')+'">EN</button></div><button class="icon-btn" data-action="settings" aria-label="'+esc(t('settings'))+'">'+icon('settings')+'</button>'+btn(t('share'),'share','share')+'</div></header><section class="hero"><img class="hero-img" src="'+images.beach+'" alt="" fetchpriority="high" referrerpolicy="no-referrer"><div class="hero-content"><div class="eyebrow">'+icon('compass')+' '+esc(t('eyebrow'))+'</div><h1>'+(state.trip.destination.toLowerCase().includes('puerto')?esc(t('heroTitle')):esc(state.trip.destination))+'</h1><p class="subtitle">'+esc(t('heroSub'))+'</p><div class="hero-meta"><button class="glass" data-action="edit-trip">'+icon('plan')+esc(formatDate(state.trip.start)+' – '+formatDate(state.trip.end))+' · '+days.length+' '+esc(t('days'))+'</button><button class="glass" data-action="edit-trip">'+icon('users')+state.trip.people+' '+esc(t('travelers'))+'</button><button class="glass" data-action="edit-trip">'+icon('sun')+esc(t(state.trip.pace))+'</button></div></div><span class="hero-caption">'+esc(state.lang==='zh'?'放慢腳步，把美好留給旅途。':'LESS RUSH. MORE WONDER.')+'</span></section><section class="intro-row"><div><h2>'+esc(t('yourTrip'))+'</h2><p>'+esc(t('tripSub'))+'</p></div><div class="toolbar">'+btn(t('editTrip'),'edit-trip','edit')+btn(t('addStop'),'add','plus','primary')+'</div></section><div class="layout '+(ui.view==='compare'?'comparison-layout':'')+'"><main><nav class="tabs">'+[['plan','itinerary','plan'],['compare','compareTab','route'],['discover','exploreTab','compass'],['stays','staysTab','bed'],['saved','savedTab','heart']].map(([v,label,ic])=>'<button data-action="view" data-view="'+v+'" class="'+(ui.view===v?'active':'')+'">'+icon(ic)+esc(t(label))+(v==='saved'?'<span class="count">'+(state.bookmarks||[]).length+'</span>':'')+'</button>').join('')+'</nav>'+(ui.view==='compare'?comparisonView({lang:state.lang,planId:ui.comparePlan,mode:ui.compareMode,stayMode:ui.compareStay,quotes:comparisonQuotes,draft:ui.quoteDraft}):ui.view==='plan'?dayView():ui.view==='map'?mapPanel():ui.view==='stays'?staysView():discovery())+'<div class="bottom-note">'+icon('check')+esc(t('localSaved'))+' · '+esc(t('photoNote'))+'</div></main><aside class="side-stack">'+(ui.view==='map'?'':mapPanel())+assistant()+'</aside></div></div>';}
function modal(title,body){const el=document.querySelector('#modal');el.innerHTML='<div class="modal-header"><h2>'+esc(title)+'</h2><button class="icon-btn" data-action="close" aria-label="'+esc(t('close'))+'">'+icon('close')+'</button></div><div class="modal-body">'+body+'</div>';if(!el.open)el.showModal();}
function tripModal(){modal(t('editTrip'),'<form id="trip-form"><label class="form-field">'+esc(t('tripName'))+'<input name="destination" required maxlength="100" value="'+esc(state.trip.destination)+'"><div class="field-note">'+esc(t('newDestination'))+'</div></label><div class="form-row"><label class="form-field">'+esc(t('start'))+'<input type="date" name="start" required value="'+state.trip.start+'"></label><label class="form-field">'+esc(t('end'))+'<input type="date" name="end" required value="'+state.trip.end+'"></label></div><div class="field-note" style="margin-bottom:14px">'+esc(t('tripRangeNote'))+'</div><div class="form-row"><label class="form-field">'+esc(t('people'))+'<input type="number" name="people" min="1" max="20" required value="'+state.trip.people+'"></label><label class="form-field">'+esc(t('pace'))+'<select name="pace">'+['relaxed','balanced','active'].map(x=>'<option value="'+x+'" '+(x===state.trip.pace?'selected':'')+'>'+esc(t(x))+'</option>').join('')+'</select></label></div><div class="form-error" role="alert"></div><div class="form-actions">'+btn(t('cancel'),'close')+'<button class="btn primary" type="submit">'+esc(t('save'))+'</button></div></form>');}
function addModal(id,slot='morning',itemId){const item=itemId?state.items.find(x=>x.id===itemId):null;const p=place(id)||state.places[0];if(!p)return;const date=item&&datesBetween(state.trip.start,state.trip.end).includes(item.date)?item.date:ui.date;const currentSlot=item?.slot||slot;modal(t(item?'edit':'addStop'),'<form id="stop-form" data-item="'+esc(itemId||'')+'">'+(item?'<div class="modal-place"><div>'+icon('pin')+'</div><div><h3>'+esc(name(p))+'</h3><p>'+esc(t(p.region))+'</p></div></div><input type="hidden" name="placeId" value="'+esc(p.id)+'">':'<label class="form-field">'+esc(t('choose'))+'<select name="placeId">'+state.places.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===p.id?'selected':'')+'>'+esc(name(x)+' · '+t(x.region))+'</option>').join('')+'</select></label>')+'<div class="form-row"><label class="form-field">'+esc(t('date'))+'<select name="date">'+datesBetween(state.trip.start,state.trip.end).map(d=>'<option value="'+d+'" '+(date===d?'selected':'')+'>'+esc(formatDate(d))+'</option>').join('')+'</select></label><label class="form-field">'+esc(t('slot'))+'<select name="slot">'+['morning','afternoon','evening'].map(s=>'<option value="'+s+'" '+(s===currentSlot?'selected':'')+'>'+esc(t(s))+'</option>').join('')+'</select></label></div><label class="form-field">'+esc(t('note'))+'<textarea name="note" rows="3" maxlength="2000" placeholder="'+esc(t('notePlaceholder'))+'">'+esc(item?.note||'')+'</textarea></label><div class="form-error" role="alert"></div><div class="form-actions">'+btn(t('cancel'),'close')+'<button class="btn primary" type="submit">'+esc(t(item?'save':'add'))+'</button></div></form>');}
function textItinerary(lang){const zh=lang==='zh';const title=p=>zh?p.zh:p.en;const labels=dict[lang];let lines=['# '+state.trip.destination,state.trip.start+' → '+state.trip.end+' · '+state.trip.people+' '+labels.travelers,''];for(const date of datesBetween(state.trip.start,state.trip.end)){lines.push('## '+date);for(const slot of ['morning','afternoon','evening']){lines.push('### '+labels[slot]);for(const item of state.items.filter(i=>i.date===date&&i.slot===slot)){const p=place(item.placeId);lines.push('- '+title(p)+' ['+labels[p.region]+']'+(item.note?' — '+item.note:''));lines.push('  '+p.source);}}for(const w of warningsFor(state.items.filter(i=>i.date===date),state.places,date))lines.push('> '+labels[({ferry:'ferryWarning',moon:'moonWarning'})[w]||w]);lines.push('');}return lines.join('\n');}
function download(content,filename,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function shareModal(){modal(t('exportTitle'),'<p class="muted small">'+esc(t('exportDesc'))+'</p><div style="display:grid;gap:10px">'+btn(t('exportJson'),'export-json','download','primary')+btn(t('exportMd'),'export-en','file')+btn(t('copy'),'copy','share')+btn(t('import'),'import','upload')+'</div><p class="field-note" style="margin-top:17px">'+esc(t('importNote'))+'</p>');}
if(staticHosting){dict.zh.setup='目前使用離線精選資料與規劃規則，不需 API 金鑰；行程儲存在自己的瀏覽器。';dict.en.setup='Uses offline curated suggestions and planning rules, with no API key required. Trip edits stay in your own browser.';}
function settingsModal(){modal(t('settingsTitle'),'<div class="settings-box"><h3>'+esc(t('aiStatus'))+' · '+esc(t(ui.aiLive?'live':'demo'))+'</h3><p>'+esc(t('setup'))+'</p></div><div class="settings-box">'+esc(t('storage'))+'<br><br>'+esc(t('mapExplain'))+'</div><h3>'+esc(t('sources'))+'</h3><div class="source-list"><a href="https://www.discoverpuertorico.com/" target="_blank" rel="noopener noreferrer">Discover Puerto Rico ↗</a><a href="https://www.puertoricoferry.com/en/buy-tickets/" target="_blank" rel="noopener noreferrer">Puerto Rico Ferry ↗</a><a href="https://www.timeanddate.com/moon/puerto-rico/san-juan?month=12&year=2026" target="_blank" rel="noopener noreferrer">Moon calendar · December 2026 ↗</a><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors ↗</a></div><div class="form-actions">'+btn(t('close'),'close')+'</div>');}
function customModal(){modal(t('newPlace'),'<form id="custom-form"><label class="form-field">'+esc(t('customName'))+'<input name="name" required maxlength="120"></label><div class="form-row"><label class="form-field">'+esc(t('lat'))+'<input name="lat" type="number" min="-90" max="90" step="any" required></label><label class="form-field">'+esc(t('lon'))+'<input name="lon" type="number" min="-180" max="180" step="any" required></label></div><div class="form-row"><label class="form-field">'+esc(t('category'))+'<select name="type">'+['sight','beach','nature','food','bio','ferry','hotel'].map(x=>'<option value="'+x+'">'+esc(t(x))+'</option>').join('')+'</select></label><label class="form-field">'+esc(t('timeEstimate'))+'<input name="duration" type="number" min="5" max="720" value="90" required></label></div><p class="field-note">'+esc(t('customNote'))+'</p><div class="form-actions">'+btn(t('cancel'),'close')+'<button class="btn primary" type="submit">'+esc(t('add'))+'</button></div></form>');}
function globalModal(){modal(t('globalSearch'),'<form id="global-form"><label class="form-field">'+esc(t('destinationPrompt'))+'<input name="city" value="'+esc(ui.globalCity)+'" placeholder="Tokyo" required maxlength="120"></label><label class="form-field">'+esc(t('category'))+'<select name="type">'+['sight','food','beach','nature','hotel'].map(x=>'<option value="'+x+'" '+(x===ui.globalType?'selected':'')+'>'+esc(t(x))+'</option>').join('')+'</select></label><div class="field-note">'+esc(t('globalHint'))+'</div><div class="form-actions">'+btn(t('cancel'),'close')+'<button class="btn primary" type="submit" '+(ui.globalStatus==='loading'?'disabled':'')+'>'+esc(t(ui.globalStatus==='loading'?'loading':'search'))+'</button></div></form><div id="global-results" style="margin-top:18px">'+(ui.globalStatus==='error'?'<div class="error-notice">'+esc(t('globalError'))+'</div>':ui.globalStatus==='empty'?'<p class="muted small">'+esc(t('globalNone'))+'</p>':ui.globalResults.map(p=>'<div class="settings-box"><strong>'+esc(p.en)+'</strong><p class="small muted">'+esc(p.descEn)+'</p>'+btn(t('add'),'add-global','plus','','data-id="'+esc(p.id)+'"')+'</div>').join(''))+'</div>');}
async function ask(prompt){if(!prompt.trim()||ui.busy)return;ui.prompt=prompt;ui.busy=true;render();try{const data=await assistantReply({prompt,lang:state.lang,trip:state.trip,date:ui.date,items:state.items,places:state.places});ui.aiLive=data.mode==='live';ui.chat=(data.fallback?t('aiError')+'\n\n':'')+data.message;ui.chatIds=(data.placeIds||[]).filter(id=>place(id));ui.chatSort=!!data.optimize;ui.prompt='';}catch{ui.chat=t('aiError');ui.chatIds=[];ui.chatSort=true;}finally{ui.busy=false;render();}}
function optimize(){const items=state.items.filter(x=>x.date===ui.date);if(!items.length){toast(t('emptyDay'));return;}mutate(()=>{state.items=state.items.filter(x=>x.date!==ui.date).concat(optimizeDay(items,state.places));},t('optimized'));}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;if(a==='search')return;if(a==='stay-add'){const p=place(id);if(!p)return;if(!state.places.some(x=>x.id===id))mutate(()=>state.places.push(p));addModal(id,'evening');const fields=document.querySelector('#stop-form');const applied=ui.stayApplied||ui.staySearch;if(datesBetween(state.trip.start,state.trip.end).includes(applied.checkin))fields.querySelector('[name="date"]').value=applied.checkin;fields.querySelector('[name="note"]').value=t('stayNote')+applied.checkin+' → '+applied.checkout+' · '+applied.guests+' '+t('guestUnit');return;}if(a==='close'){document.querySelector('#modal').close();return;}if(a==='lang'){state.lang=b.dataset.lang;ui.compareMode=state.lang;ui.chat='';ui.chatIds=[];persist();render();return;}if(a==='view'){ui.view=b.dataset.view;ui.query='';ui.filter='all';ui.region='all';render();window.scrollTo({top:300,behavior:'smooth'});return;}if(a==='date'){ui.date=b.dataset.date;render();return;}if(a==='edit-trip'){tripModal();return;}if(a==='add'){if(id&&!state.places.some(p=>p.id===id)&&place(id))mutate(()=>state.places.push(place(id)));addModal(id,b.dataset.slot||(place(id)?.type==='bio'?'evening':'morning'));return;}if(a==='edit-item'){const item=state.items.find(x=>x.id===id);addModal(item.placeId,item.slot,id);return;}if(a==='bookmark'){mutate(()=>{if(!state.places.some(p=>p.id===id)&&place(id))state.places.push(place(id));state.bookmarks=state.bookmarks||[];state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];},t((state.bookmarks||[]).includes(id)?'unbookmarked':'bookmarked'));return;}if(a==='remove'){mutate(()=>{state.items=state.items.filter(x=>x.id!==id);},t('removed'));return;}if(a==='move-up'||a==='move-down'){const item=state.items.find(x=>x.id===id);const items=state.items.filter(x=>x.date===item.date&&x.slot===item.slot);const n=items.findIndex(x=>x.id===id),next=n+(a==='move-up'?-1:1);if(next<0||next>=items.length)return;mutate(()=>{const i=state.items.indexOf(item),j=state.items.indexOf(items[next]);[state.items[i],state.items[j]]=[state.items[j],state.items[i]];});return;}if(a==='undo'){if(ui.undo){const prev=structuredClone(state);state=ui.undo;ui.undo=prev;persist();render();toast(t('undone'));}return;}if(a==='optimize'){optimize();return;}if(a==='locate'){ui.selected=id;if(ui.mapScope==='day'&&!state.items.some(i=>i.date===ui.date&&i.placeId===id))ui.mapScope='all';render();if(innerWidth<900)document.querySelector('#map-panel')?.scrollIntoView({behavior:'smooth',block:'center'});return;}if(a==='map-mode'){ui.mapMode=b.dataset.mode;render();return;}if(a==='map-scope'){ui.mapScope=ui.mapScope==='all'?'day':'all';ui.zoom=1;render();return;}if(a==='zoom-in'||a==='zoom-out'||a==='zoom-reset'){ui.zoom=a==='zoom-reset'?1:Math.max(1,Math.min(8,ui.zoom*(a==='zoom-in'?1.5:1/1.5)));render();return;}if(a==='filter'){ui.filter=b.dataset.filter;render();return;}if(a==='prompt'){await ask(t(b.dataset.prompt));return;}if(a==='share'){shareModal();return;}if(a==='settings'){settingsModal();return;}if(a==='export-json'){download(JSON.stringify(state,null,2),'isla-trip.json','application/json');return;}if(a==='export-en'){download(textItinerary('en'),'isla-itinerary-en.md','text/markdown');return;}if(a==='copy'){try{await navigator.clipboard.writeText(textItinerary(state.lang));toast(t('copied'));}catch{download(textItinerary(state.lang),'isla-itinerary.txt');toast(t('copyFail'));}return;}if(a==='import'){document.querySelector('#import-file').value='';document.querySelector('#import-file').click();return;}if(a==='custom'){customModal();return;}if(a==='global'){ui.globalStatus='';globalModal();return;}if(a==='add-global'){const p=ui.globalResults.find(x=>x.id===id);if(p){if(!place(id))mutate(()=>{state.places.push(p);});ui.selected=id;ui.mapScope='all';addModal(id);}return;}});
document.addEventListener('keydown',e=>{if(e.target.matches('.map-pin')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.target.id==='ai-prompt'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();ask(e.target.value);}});
document.addEventListener('input',e=>{if(e.target.closest('#stay-form')&&e.target.name)ui.staySearch[e.target.name]=e.target.value;if(e.target.id==='ai-prompt')ui.prompt=e.target.value;});
document.addEventListener('change',async e=>{if(e.target.id==='stay-sort'){ui.staySort=e.target.value;render();return;}if(e.target.id==='stay-compare'){ui.date=e.target.value;render();return;}if(e.target.id==='region-filter'){ui.region=e.target.value;render();}if(e.target.id==='import-file'&&e.target.files[0]){try{if(e.target.files[0].size>2000000)throw new Error();const data=validateImport(JSON.parse(await e.target.files[0].text()));mutate(()=>{state=data;ui.date=data.trip.start;ui.selected=data.places[0]?.id;ui.view='plan';ui.chat='';},t('imported'));document.querySelector('#modal').close();}catch{toast(t('importError'));}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));const err=form.querySelector('.form-error');if(form.id==='stay-form'){ui.staySearch={...values,city:values.city.trim(),guests:Number(values.guests)};try{stayNights(values.checkin,values.checkout);if(!values.city.trim()||!Number.isInteger(+values.guests)||+values.guests<1||+values.guests>20)throw new Error();}catch{ui.stayError=t('stayDatesError');render();return;}ui.stayError='';ui.stayStatus='loading';ui.stayResults=[];ui.stayApplied={...ui.staySearch};render();try{const data=await findPlaces(ui.staySearch.city,'hotel');ui.stayResults=data.places;ui.stayStatus=data.places.length?'done':'empty';if(data.places.length){ui.selected=data.places[0].id;ui.mapScope='all';ui.zoom=3;}}catch{ui.stayStatus='error';}render();return;}if(form.id==='search-form'){ui.query=values.query;render();return;}if(form.id==='ask-form'){await ask(values.prompt);return;}if(form.id==='trip-form'){try{datesBetween(values.start,values.end);}catch{err.textContent=t('rangeError');return;}if(!values.destination.trim()){err.textContent=t('tripName');return;}if(!Number.isInteger(+values.people)||+values.people<1||+values.people>20){err.textContent=t('peopleError');return;}mutate(()=>{state.trip={...values,destination:values.destination.trim(),people:+values.people};ui.date=values.start;},t('updated'));document.querySelector('#modal').close();return;}if(form.id==='stop-form'){const editId=form.dataset.item;if(state.items.some(x=>x.id!==editId&&x.date===values.date&&x.slot===values.slot&&x.placeId===values.placeId)){err.textContent=t('duplicate');return;}mutate(()=>{if(editId){const item=state.items.find(x=>x.id===editId);Object.assign(item,values);}else state.items.push({id:uid(),...values});ui.date=values.date;ui.view='plan';ui.selected=values.placeId;},t(editId?'updated':'added'));document.querySelector('#modal').close();return;}if(form.id==='custom-form'){const lat=+values.lat,lon=+values.lon;if(!values.name.trim()||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return;const p={id:'custom-'+uid(),zh:values.name.trim(),en:values.name.trim(),descZh:dict.zh.geographic,descEn:dict.en.geographic,lat,lon,type:values.type,duration:+values.duration,region:'other',tags:'custom',image:values.type==='food'?'food':'beach',source:'https://www.openstreetmap.org/?mlat='+lat+'&mlon='+lon+'#map=15/'+lat+'/'+lon};mutate(()=>{state.places.push(p);});addModal(p.id);return;}if(form.id==='global-form'){ui.globalCity=values.city;ui.globalType=values.type;ui.globalStatus='loading';ui.globalResults=[];globalModal();try{const data=await findPlaces(values.city,values.type);ui.globalResults=data.places;ui.globalStatus=data.places.length?'done':'empty';}catch{ui.globalStatus='error';}if(document.querySelector('#global-form'))globalModal();return;}});

function comparisonPreview(id){
 const previewLang=ui.compareMode==='both'?state.lang:ui.compareMode;const p=plans.find(x=>x.id===id);if(!p)return;const c=comparisonCopy[previewLang],items=planItems(id);
 modal(c.applyTitle+' · '+id,'<h3>'+esc(p.title[previewLang])+'</h3><p class="small">'+esc(c.applyText)+'</p><p class="small muted">'+esc(c.intro)+'</p><ol class="plan-preview-days">'+datesBetween(context.start,context.end).map(date=>'<li><strong>'+esc(date)+'</strong> · '+esc(date===context.start?c.arrival+(items.some(x=>x.date===date)?' + '+c.bioTrip:''):date===context.end?c.departure:items.filter(x=>x.date===date).map(x=>{const p=state.places.find(y=>y.id===x.placeId)||seed.find(y=>y.id===x.placeId);return previewLang==='zh'?p.zh:p.en;}).join(' → '))+'</li>').join('')+'</ol><p class="small">'+esc(c[ui.compareStay+'Text'])+'</p><div class="form-actions">'+btn(dict[previewLang].cancel,'close')+btn(c.applyConfirm,'compare-apply','check','primary','data-id="'+id+'"')+'</div>');
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,c=comparisonCopy[state.lang];
 if(a==='compare-jump')document.getElementById(b.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(a==='compare-select'){ui.comparePlan=b.dataset.id;render();}
 if(a==='compare-mode'){ui.compareMode=b.dataset.mode;state.lang=b.dataset.mode;persist();render();}
 if(a==='compare-stay'){ui.compareStay=b.dataset.mode;render();}
 if(a==='compare-preview')comparisonPreview(b.dataset.id);
 if(a==='compare-apply'){
  const id=b.dataset.id,items=planItems(id);mutate(()=>{for(const item of items)if(!state.places.some(p=>p.id===item.placeId))state.places.push(structuredClone(seed.find(p=>p.id===item.placeId)));state.trip={...state.trip,destination:'Puerto Rico',start:context.start,end:context.end,people:2,comparisonPlan:id,comparisonVersion:2,comparisonStay:ui.compareStay};state.items=items;ui.date=context.start;ui.view='plan';ui.staySearch={city:'San Juan, Puerto Rico',checkin:context.start,checkout:context.end,guests:2};},c.applied);document.querySelector('#modal').close();document.querySelector('.tabs').scrollIntoView({behavior:'smooth'});
 }
 if(a==='compare-search'){ui.staySearch={city:b.dataset.area==='east'?'Luquillo, Puerto Rico':'San Juan, Puerto Rico',checkin:b.dataset.area==='east'?'2026-12-22':context.start,checkout:context.end,guests:2};ui.stayResults=[];ui.stayStatus='';ui.stayError='';ui.view='stays';render();document.querySelector('#stay-form').scrollIntoView({behavior:'smooth'});}
 if(a==='compare-export')download(comparisonMarkdown(),'puerto-rico-options-zh-en.md','text/markdown');
 if(a==='compare-clear'){comparisonQuotes={};ui.quoteDraft={};try{localStorage.removeItem('isla-comparison-quotes-v1');}catch{toast(t('persistError'));}render();}
});
document.addEventListener('input',e=>{if(e.target.closest('#comparison-quotes')&&e.target.name)ui.quoteDraft[e.target.name]=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id!=='comparison-quotes')return;e.preventDefault();const c=comparisonCopy[state.lang];try{const q=parseQuote(Object.fromEntries(new FormData(e.target)));localStorage.setItem('isla-comparison-quotes-v1',JSON.stringify(q));comparisonQuotes=q;ui.quoteDraft={};render();toast(c.saved);document.querySelector('#quote-calculator').scrollIntoView({block:'start'});}catch{e.target.querySelector('.form-error').textContent=c.invalid;}});

render();assistantStatus().then(x=>{ui.aiLive=x.aiConfigured;render();}).catch(()=>{});
